import { useEffect, useState, useCallback, useMemo } from "react";
import { View, Text, ScrollView, Pressable, ActivityIndicator, StyleSheet } from "react-native";
import { useLocalSearchParams, useRouter } from "expo-router";
import { MaterialCommunityIcons } from "@expo/vector-icons";
import AsyncStorage from "@react-native-async-storage/async-storage";
import Button from "../../../components/Button";
import Breadcrumbs from "../../../components/Breadcrumbs";
import { loadCourse } from "../../../utils/courseLoader";
import { Course } from "../../../data/types";
import { useThemeContext } from "../../../components/ThemeProvider";
import { Colors } from "../../../constants/Colors";
import { isExerciseLocked as checkExerciseLocked } from "../../../utils/isExerciseLocked";

export default function CourseDetail() {
 const { course } = useLocalSearchParams<{ course: string }>();
 const router = useRouter();
 const [courseData, setCourseData] = useState<Course | null>(null);
 const [loading, setLoading] = useState(true);
 const [completedLessons, setCompletedLessons] = useState<string[]>([]);
 const [error, setError] = useState<string | null>(null);
 const { colorScheme, derivedColors } = useThemeContext();
 const colors = Colors[colorScheme === "dark" ? "dark" : "light"];

 const loadData = useCallback(async () => {
 if (!course) return;
 setError(null);
 try {
 const data = await loadCourse(course);
 setCourseData(data);
 try {
 const val = await AsyncStorage.getItem("completedLessons");
 if (val) setCompletedLessons(JSON.parse(val));
 } catch {}
 } catch (e) {
 setError(e instanceof Error ? e.message : "Failed to load course");
 } finally {
 setLoading(false);
 }
 }, [course]);

 useEffect(() => {
 loadData();
 }, [loadData]);

 const nextExerciseIdx = useMemo(() => {
 if (!courseData || !course) return -1;
 return courseData.exercises.findIndex(
 (_, i) => !completedLessons.includes(`${course}/${courseData.exercises[i].id}`)
 );
 }, [courseData, completedLessons, course]);

 const nextExercise = useMemo(() => {
 if (!courseData || nextExerciseIdx < 0) return null;
 return courseData.exercises[nextExerciseIdx];
 }, [courseData, nextExerciseIdx]);

 const upNextLessons = useMemo(() => {
 if (!courseData || nextExerciseIdx < 0) return [];
 return courseData.exercises.slice(nextExerciseIdx + 1);
 }, [courseData, nextExerciseIdx]);

 const completedLessonItems = useMemo(() => {
 if (!courseData || !course) return [];
 return courseData.exercises.filter(
 (l) => completedLessons.includes(`${course}/${l.id}`)
 );
 }, [courseData, completedLessons, course]);

 const progress = useMemo(() => {
 if (!courseData || courseData.exercises.length === 0) return 0;
 const courseCompleted = completedLessons.filter((id) =>
 id.startsWith(`${course}/`)
 ).length;
 return courseCompleted / courseData.exercises.length;
 }, [courseData, completedLessons, course]);

  function isLessonLocked(index: number) {
    if (!course || !courseData) return true;
    return checkExerciseLocked(completedLessons, course, courseData.exercises[index].id, courseData.exercises);
  }

if (loading) {
 return (
 <View style={[styles.container, { backgroundColor: colors.surface }]}>
 <View
 style={[
 styles.header,
 { backgroundColor: colors.surface },
 ]}
 >
 <View style={{ width: 40 }} />
 <Text style={[styles.headerTitle, { color: derivedColors.primary }]}>
 Course
 </Text>
 <View style={{ width: 40 }} />
 </View>
 <View style={styles.centeredContainer}>
 <ActivityIndicator size="large" color={derivedColors.primary} />
 </View>
 </View>
 );
 }

if (error) {
  return (
  <View style={[styles.container, { backgroundColor: colors.surface }]}>
  <View
  style={[
    styles.header,
    { backgroundColor: colors.surface },
  ]}
  >
  <Pressable onPress={() => router.back()} style={styles.backButton}>
 <MaterialCommunityIcons
 name="arrow-left"
 size={24}
 color={derivedColors.primary}
 />
 </Pressable>
 <Text style={[styles.headerTitle, { color: derivedColors.primary }]}>
 Course
 </Text>
 <View style={{ width: 40 }} />
 </View>
 <View style={styles.notFoundContainer}>
 <Text style={[styles.notFoundTitle, { color: colors.onSurface }]}>
 Load Error
 </Text>
 <Text
 style={[styles.notFoundSubtitle, { color: colors.textSecondary }]}
 >
 {error}
 </Text>
 <View style={styles.notFoundButtonWrapper}>
<Pressable
  onPress={() => router.back()}
  style={({ pressed }) => [
 styles.backButton,
 pressed && styles.backButtonPressed,
 ]}
 accessibilityRole="button"
 accessibilityLabel="Back to courses"
 >
 <Text style={styles.backButtonText}>
 Back to courses
 </Text>
 </Pressable>
 </View>
 </View>
 </View>
 );
 }

if (!courseData) {
  return (
  <View style={[styles.container, { backgroundColor: colors.surface }]}>
  <View
  style={[
    styles.header,
    { backgroundColor: colors.surface },
  ]}
  >
  <Pressable onPress={() => router.back()} style={styles.backButton}>
 <MaterialCommunityIcons
 name="arrow-left"
 size={24}
 color={derivedColors.primary}
 />
 </Pressable>
 <Text style={[styles.headerTitle, { color: derivedColors.primary }]}>
 Course
 </Text>
 <View style={{ width: 40 }} />
 </View>
 <View style={styles.notFoundContainer}>
 <Text style={[styles.notFoundTitle, { color: colors.onSurface }]}>
 Course not found
 </Text>
 <Text
 style={[styles.notFoundSubtitle, { color: colors.textSecondary }]}
 >
 The course &ldquo;{course}&rdquo; doesn&apos;t exist yet.
 </Text>
 </View>
 </View>
);
 }

 return (
 <View style={[styles.container, { backgroundColor: colors.surface }]}>
    <View
      style={[
        styles.header,
        { backgroundColor: colors.surface },
      ]}
      >
<Pressable onPress={() => router.back()} style={styles.backButton}>
        <MaterialCommunityIcons
          name="arrow-left"
          size={24}
          color={derivedColors.primary}
        />
        </Pressable>
      <View style={{ flex: 1 }} />
      </View>

      <Breadcrumbs
        segments={[
          { label: "Learn", href: "/learn" },
          { label: courseData.title },
        ]}
      />

      <ScrollView
 style={styles.scrollView}
 contentContainerStyle={styles.scrollContent}
 >
 {nextExercise && (
 <View
 style={[
 styles.heroSection,
 { backgroundColor: colors.surfaceContainerLow },
 ]}
 >
  <Text style={[styles.heroLabel, { color: derivedColors.primary }]}>
  Next exercise
  </Text>
 <Text style={[styles.heroTitle, { color: colors.onSurface }]}>
 {nextExercise.title}
 </Text>
 <View style={styles.heroDescriptionRow}>
 <View
 style={[
 styles.heroAccent,
 { backgroundColor: derivedColors.primary },
 ]}
 />
 <Text
 style={[
 styles.heroDescription,
 { color: colors.textSecondary },
 ]}
 >
 {nextExercise.description}
 </Text>
 </View>
 <Button
 title="START"
 variant="primary"
 onPress={() =>
 router.push(`/learn/${course}/${nextExercise.id}`)
 }
 />
 <View
 style={[
 styles.progressTrack,
 { backgroundColor: colors.surfaceContainerHigh },
 ]}
 >
 <View
 style={{
 flex: progress,
 backgroundColor: derivedColors.primary,
 }}
 />
 <View style={{ flex: 1 - progress }} />
 </View>
 </View>
)}

 {upNextLessons.length > 0 && (
 <View style={styles.section}>
 <View style={styles.sectionHeader}>
 <Text style={[styles.sectionTitle, { color: derivedColors.primary }]}>
 Up Next
 </Text>
 <Text
 style={[
 styles.sectionSubtitle,
 { color: colors.textSecondary },
 ]}
 >
 {courseData.moduleName}
 </Text>
 </View>
 <View style={styles.lessonList}>
 {upNextLessons.map((lesson, index) => {
 const globalIdx = nextExerciseIdx + 1 + index;
 const locked = isLessonLocked(globalIdx);
 const isLast = index === upNextLessons.length - 1;
 return (
 <Pressable
 key={lesson.id}
 disabled={locked}
 onPress={() =>
 router.push(`/learn/${course}/${lesson.id}`)
 }
 style={({ pressed }) => [
  styles.lessonRow,
  isLast && styles.lessonRowLast,
  { borderColor: locked ? "transparent" : colors.outlineVariant },
  pressed &&
  !locked && {
  backgroundColor: colors.surfaceContainerHigh,
  },
  ]}
  >
  <View
  style={[
  styles.lessonIcon,
  { borderColor: locked ? "transparent" : colors.outlineVariant },
  ]}
 >
 {locked || isLast ? (
 <MaterialCommunityIcons
 name={isLast ? "trophy" : "lock"}
 size={20}
 color={isLast ? derivedColors.primary : colors.textSecondary}
 />
) : (
 <MaterialCommunityIcons
 name="play-circle-outline"
 size={20}
 color={derivedColors.primary}
 />
)}
 </View>
 <View style={styles.lessonInfo}>
 <Text
 style={[
 styles.lessonTitle,
 {
 color: locked
 ? colors.textSecondary
 : colors.onSurface,
 },
 ]}
 >
 {lesson.title}
 </Text>
 <Text
 style={[
 styles.lessonModule,
 { color: colors.textSecondary },
 ]}
 >
 {isLast
 ? `Earn ${courseData.moduleName} Badge`
  : lesson.module}
 </Text>
 </View>
 <MaterialCommunityIcons
 name="chevron-right"
 size={20}
 color={colors.textSecondary}
 />
 </Pressable>
);
 })}
 </View>
 </View>
)}

 {completedLessonItems.length > 0 && (
 <View
 style={[
 styles.completedSection,
 {
 borderTopColor: colors.onSurface + "1A",
 },
 ]}
 >
  <Text style={[styles.completedLabel, { color: colors.onSurface }]}>
  Completed
  </Text>
 {completedLessonItems.map((lesson) => (
 <Pressable
 key={lesson.id}
 onPress={() => router.push(`/learn/${course}/${lesson.id}`)}
 style={({ pressed }) => [
 styles.completedRow,
 pressed && { backgroundColor: colors.surfaceContainerHigh },
 ]}
 >
 <MaterialCommunityIcons
 name="check-circle"
 size={18}
 color={derivedColors.primary}
 />
 <Text
 style={[
 styles.completedTitle,
 { color: colors.onSurface },
 ]}
 >
 {lesson.title}
 </Text>
 <MaterialCommunityIcons
 name="chevron-right"
 size={16}
 color={colors.textSecondary}
 />
 </Pressable>
 ))}
 </View>
)}
 </ScrollView>
 </View>
);
}

