function getExtensions() {
  var exts = [
    basicSetup,
    javascript(),
    p5Theme,
    syntaxHighlighting(p5Highlight),
    p5FnPlugin,
    autocompletion({ override: [p5CompletionSource] }),
    keymap.of([{ key: 'Ctrl-s', run: function() { return true; } }, { key: 'Cmd-s', run: function() { return true; } }]),
